BEGIN;
create temp table checks(label text);
create function pg_temp.check(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;insert into checks values(label);end$$;
create temp table fixture(property_id uuid,actor_id uuid,lead_id uuid);
insert into fixture select gen_random_uuid(),id,gen_random_uuid() from public.profiles where org_id='22222222-2222-2222-2222-222222222222' and role='admin' limit 1;
insert into public.properties(id,org_id,name) select property_id,'22222222-2222-2222-2222-222222222222','LeadPulse SQL fixture' from fixture;
insert into public.leads(id,property_id,first_name,email,source,created_at) select lead_id,property_id,'Fixture','private-fixture@example.invalid','website form',now()-interval '25 hours' from fixture;
DO $$declare p uuid;actor uuid;l uuid;r jsonb;again jsonb;sid uuid;eid uuid;req uuid:=gen_random_uuid();cor uuid:=gen_random_uuid();batch uuid:=gen_random_uuid();captured_input jsonb;n int;
begin
 select property_id,actor_id,lead_id into p,actor,l from fixture;
 perform pg_temp.check(public.read_leadpulse_score(p,actor,l)->>'state'='unscored','opening an unscored lead is read-only');
 perform pg_temp.check((select count(*)=0 from public.lead_scores where lead_id=l),'score read creates no score');
 r:=public.record_lead_engagement(p,l,'call_inbound','{"note":"Private call note"}','operator/'||req,'operator',actor);
 perform pg_temp.check(r->>'state'='applied','reported event saved with score');
 sid:=(r->>'scoreId')::uuid;eid:=(r->>'eventId')::uuid;
 perform pg_temp.check((select timing_score=20 and source_score=20 and engagement_score=20 from public.lead_scores where id=sid),'rules use actual 24-hour boundary and assigned source/event points');
 select i.input into captured_input from public.lead_score_inputs i where score_id=sid;
 perform pg_temp.check(captured_input->'events'->0->>'origin'='operator','scoring input retains actual reporting origin');
 perform pg_temp.check(captured_input::text not like '%Private call note%' and captured_input::text not like '%private-fixture%','scoring snapshot excludes contact and free text');
 perform pg_temp.check((select input_hash=encode(sha256(convert_to(i.input::text,'UTF8')),'hex') from public.lead_score_inputs i where score_id=sid),'snapshot hash matches exact input');
 again:=public.record_lead_engagement(p,l,'call_inbound','{"note":"Private call note"}','operator/'||req,'operator',actor);
 perform pg_temp.check(again->>'state'='replayed' and again->>'scoreId'=sid::text,'duplicate event recovers original score');
 perform pg_temp.check((select count(*)=1 from public.lead_scores where lead_id=l),'event retry does not rescore');
 perform pg_temp.check(public.record_lead_engagement(p,l,'email_opened','{}','operator/'||req,'operator',actor)->>'state'='request_conflict','changed event cannot reuse identity');
 perform pg_temp.check(public.record_lead_engagement(p,l,'tour_completed','{}','operator/'||gen_random_uuid(),'operator',actor)->>'state'='use_tour_workflow','manual report cannot bypass tour outcome workflow');
 perform pg_temp.check(public.record_lead_engagement(p,l,'email_opened','{}','operator/'||gen_random_uuid(),'operator',gen_random_uuid())->>'state'='forbidden','current actor membership enforced');
 perform pg_temp.check((select count(*)=1 from public.shared_action_events where property_id=p and action='lead.engagement.recorded' and not training_eligible),'one recorded decision excluded from training');
 perform pg_temp.check((select result::text not like '%Private call note%' and request::text not like '%Private call note%' from public.shared_action_events where property_id=p and action='lead.engagement.recorded'),'shared action contains no raw metadata');
 r:=public.correct_lead_engagement(p,l,eid,actor,cor,'Reported in error');
 perform pg_temp.check(r->>'state'='applied','reported engagement can be withdrawn');
 perform pg_temp.check((select engagement_score=0 from public.lead_scores where id=(r->>'scoreId')::uuid),'correction recalculates without withdrawn event');
 perform pg_temp.check((select count(*)=1 from public.lead_engagement_events where id=eid),'correction preserves original event');
 perform pg_temp.check(public.correct_lead_engagement(p,l,eid,actor,cor,'Reported in error')->>'state'='replayed','correction retry is stable');
 perform pg_temp.check(public.correct_lead_engagement(p,l,eid,actor,gen_random_uuid(),'Reported in error')->>'state'='already_corrected','second withdrawal cannot stack');
 perform pg_temp.check(public.correct_lead_engagement(p,l,eid,actor,cor,'New reason')->>'state'='request_conflict','correction identity binds reason');
 r:=public.record_lead_engagement(p,l,'chat_started','{"conversation_id":"fixture"}','luma/'||req,'lumaleasing');
 perform pg_temp.check(r->>'state'='applied','system event uses private source receipt without invented actor');
 perform pg_temp.check(public.correct_lead_engagement(p,l,(r->>'eventId')::uuid,actor,gen_random_uuid(),'Reported in error')->>'state'='not_reported','system evidence cannot be withdrawn as operator report');
 perform pg_temp.check(exists(select 1 from jsonb_array_elements(public.read_leadpulse_events(p,actor,l)->'events') e where e->>'id'=eid::text and e->>'corrected'='true'),'review lists withdrawn event');
 perform pg_temp.check(public.read_leadpulse_score(p,actor,l)->'provenance'->>'status'='captured','score presents provenance status');
 perform pg_temp.check(not has_table_privilege('authenticated','public.lead_score_inputs','select'),'browser cannot read private input IDs');
 perform pg_temp.check(not has_function_privilege('authenticated','public.score_lead(uuid)','execute'),'browser cannot bypass recorded rescore');
 perform pg_temp.check(not has_table_privilege('authenticated','public.lead_engagement_events','insert'),'browser cannot forge weighted events');
 begin update public.lead_score_inputs set input='{}' where score_id=sid;raise exception 'FAIL mutable';exception when raise_exception then if SQLERRM<>'LeadPulse evidence is immutable' then raise;end if;end;
 perform pg_temp.check((select i.input=captured_input from public.lead_score_inputs i where score_id=sid),'score input immutable');
 -- More than the former 500-lead silent cap, processed in recoverable pages.
 insert into public.leads(property_id,first_name,source) select p,'Batch fixture','referral' from generate_series(1,503);
 r:=public.run_lead_score_batch(p,actor,batch);
 perform pg_temp.check((r->>'total')::int=504 and (r->>'successful')::int=25 and (r->>'pending')::int=479,'all targets saved beyond 500, first page bounded');
 perform pg_temp.check(public.run_lead_score_batch(p,actor,gen_random_uuid())->>'state'='busy','second open run held');
 perform pg_temp.check(public.run_lead_score_batch(p,actor,batch,array[l])->>'state'='request_conflict','saved selection cannot change');
 perform pg_temp.check(public.lead_score_batch_status(p,actor,batch)->>'successful'='25','read status never advances batch');
 r:=public.continue_lead_score_batch(p,actor,batch);
 perform pg_temp.check((r->>'successful')::int=50,'resume processes next targets once');
 r:=public.cancel_lead_score_batch(p,actor,batch,req);
 perform pg_temp.check(r->>'state'='cancelled' and r->>'successful'='50','stop retains completed scores and pending manifest');
 perform pg_temp.check(public.continue_lead_score_batch(p,actor,batch)->>'state'='cancelled','late continuation cannot revive stopped run');
 perform pg_temp.check(public.cancel_lead_score_batch(p,actor,batch,req)->>'state'='cancelled','stop retry recovers result');
 batch:=gen_random_uuid();r:=public.run_lead_score_batch(p,actor,batch,array[l]);
 perform pg_temp.check(r->>'state'='completed' and r->>'successful'='1','single rescore completes with evidence');
 sid:=(r->>'scoreId')::uuid;r:=public.run_lead_score_batch(p,actor,batch,array[l]);
 perform pg_temp.check(r->>'scoreId'=sid::text,'lost single response replays original score');
 perform pg_temp.check((select count(*)=1 from public.shared_action_events where episode_id=batch and action='lead.score.recalculated'),'single retry adds no duplicate action');
end$$;
-- Database aggregate queries must cover the complete property and deduplicate daily lead counts.
DO $$declare p uuid;actor uuid;l uuid;r jsonb;peer uuid:=gen_random_uuid();batch uuid:=gen_random_uuid();stop uuid:=gen_random_uuid();
begin
 select property_id,actor_id,lead_id into p,actor,l from fixture;
 r:=public.read_leadpulse_insights(p,actor);
 perform pg_temp.check(r->'insights'->>'totalLeads'='504','insights include all property leads');
 perform pg_temp.check((r->'insights'->>'scoredLeads')::int<=51,'scored count counts leads, not score attempts');
 perform pg_temp.check((r->'insights'->'recentTrend'->0->>'scoredLeads')::int<=51,'daily trend counts each lead once');
 perform pg_temp.check(public.list_leadpulse_leads(p,actor,'Batch fixture','all',1)->>'total'='503','search covers all matching leads');
 perform pg_temp.check(jsonb_array_length(public.list_leadpulse_leads(p,actor,'Batch fixture','all',11)->'leads')=3,'last page includes leads beyond former cap');
 perform pg_temp.check(public.read_leadpulse_insights(p,gen_random_uuid())->>'state'='forbidden','insights enforce current membership in database');
 insert into auth.users(id,email) values(peer,peer::text||'@fixture.invalid');
 update public.profiles set org_id='22222222-2222-2222-2222-222222222222' where id=peer;
 r:=public.run_lead_score_batch(p,actor,batch);
 perform pg_temp.check(public.continue_lead_score_batch(p,peer,batch)->>'state'='owner_required','another operator cannot silently continue attributed work');
 perform pg_temp.check(public.cancel_lead_score_batch(p,peer,batch,stop)->>'state'='cancelled','teammate can stop remaining work with own attribution');
 perform pg_temp.check((select actor_id=peer from public.shared_action_events where id=stop),'stop preserves actual intervening actor');
 update public.profiles set org_id=null where id=peer;
 perform pg_temp.check(public.cancel_lead_score_batch(p,peer,batch,stop)->>'state'='forbidden','removed operator cannot replay former decision');
end$$;
create function pg_temp.fail_leadpulse_score() returns trigger language plpgsql as $$begin if new.lead_id=(select lead_id from fixture) then raise exception 'Fixture scoring failure';end if;return new;end$$;
create trigger leadpulse_fixture_failure before insert on public.lead_scores for each row execute function pg_temp.fail_leadpulse_score();
create temp table failed_run(id uuid);
DO $$declare p uuid;actor uuid;l uuid;r jsonb;batch uuid:=gen_random_uuid();n int;
begin
 select property_id,actor_id,lead_id into p,actor,l from fixture;
 select count(*) into n from public.lead_engagement_events where lead_id=l;
 begin perform public.record_lead_engagement(p,l,'email_opened','{}','failure-fixture','operator',actor);raise exception 'FAIL partial event';exception when raise_exception then if SQLERRM<>'Fixture scoring failure' then raise;end if;end;
 perform pg_temp.check((select count(*)=n from public.lead_engagement_events where lead_id=l),'failed scoring rolls back engagement insert');
 perform pg_temp.check(not exists(select 1 from public.lead_engagement_receipts where property_id=p and request_key='failure-fixture'),'failed scoring rolls back pending receipt');
 select count(*) into n from public.lead_scores where lead_id=l;
 r:=public.run_lead_score_batch(p,actor,batch,array[l]);insert into failed_run values(batch);
 perform pg_temp.check(r->>'failed'='1' and r->>'successful'='0' and r->>'state'='completed','failed score reported as failure, not null success');
 perform pg_temp.check((select count(*)=n from public.lead_scores where lead_id=l),'failed item leaves no partial score');
 perform pg_temp.check((select phase='failed' from public.shared_action_events where episode_id=batch and action='lead.scoring.completed'),'failed run outcome is recorded');
end$$;
drop trigger leadpulse_fixture_failure on public.lead_scores;
DO $$declare p uuid;actor uuid;l uuid;r jsonb;batch uuid:=gen_random_uuid();
begin
 select property_id,actor_id,lead_id into p,actor,l from fixture;
 r:=public.run_lead_score_batch(p,actor,batch,null,(select id from failed_run));
 perform pg_temp.check(r->>'successful'='1' and r->>'failed'='0' and r->>'total'='1','retry captures only failed targets in a new attributed run');
 perform pg_temp.check(public.lead_score_batch_status(p,actor,(select id from failed_run))->>'failed'='1','retry preserves original failure history');
end$$;
create function pg_temp.fail_leadpulse_action() returns trigger language plpgsql as $$begin if new.action='lead.engagement.recorded' then raise exception 'Fixture history failure';end if;return new;end$$;
create trigger leadpulse_fixture_action_failure before insert on public.shared_action_events for each row execute function pg_temp.fail_leadpulse_action();
DO $$declare p uuid;actor uuid;l uuid;n int;
begin
 select property_id,actor_id,lead_id into p,actor,l from fixture;
 select count(*) into n from public.lead_scores where lead_id=l;
 begin perform public.record_lead_engagement(p,l,'email_opened','{}','action-failure-fixture','operator',actor);raise exception 'FAIL unrecorded event';exception when raise_exception then if SQLERRM<>'Fixture history failure' then raise;end if;end;
 perform pg_temp.check((select count(*)=n from public.lead_scores where lead_id=l),'history failure rolls back score and snapshot');
 perform pg_temp.check(not exists(select 1 from public.lead_engagement_events where lead_id=l and idempotency_key='action-failure-fixture'),'history failure rolls back weighted event');
end$$;

DO $$declare p uuid;actor uuid;l uuid;s uuid;oldscore uuid;req uuid:=gen_random_uuid();r jsonb;n int;
begin
 select property_id,actor_id,lead_id into p,actor,l from fixture;
 select id into s from public.lead_scores where lead_id=l order by scored_at desc,id desc limit 1;
 select count(*) into n from public.lead_scores where lead_id=l;
 r:=public.review_lead_score(p,l,s,actor,req,'too_high','Needs a verified move-in timeline.');
 perform pg_temp.check(r->>'state'='applied','assessment attached to exact saved score');
 perform pg_temp.check(public.review_lead_score(p,l,s,actor,req,'too_high','Needs a verified move-in timeline.')->>'state'='replayed','lost assessment response replays once');
 perform pg_temp.check(public.review_lead_score(p,l,s,actor,req,'too_low','Needs a verified move-in timeline.')->>'state'='request_conflict','assessment identity binds judgment');
 perform pg_temp.check((select count(*)=n from public.lead_scores where lead_id=l),'assessment does not alter scoring rules or score');
 perform pg_temp.check((select not training_eligible and result->>'evidenceKind'='operator_assessment' and request::text not like '%verified move-in%' from public.shared_action_events where id=req),'assessment is opinion with private reason, excluded from training');
 perform pg_temp.check(public.read_lead_score_reviews(p,l,actor)->'reviews'->0->>'score_id'=s::text,'review history displays exact score identity');
 oldscore:=s;s:=public.score_lead(l);
 perform pg_temp.check(public.review_lead_score(p,l,oldscore,actor,gen_random_uuid(),'useful','Old score review')->>'state'='stale_score','new assessment of superseded score held');
 perform pg_temp.check(public.review_lead_score(p,l,oldscore,actor,req,'too_high','Needs a verified move-in timeline.')->>'state'='replayed','acknowledged assessment keeps original score after later rescore');
 perform pg_temp.check((select score=(select total_score from public.lead_scores where id=s) and score_bucket=(select score_bucket from public.lead_scores where id=s) from public.leads where id=l),'lead list cache matches latest score');
end$$;

DO $$declare p uuid;actor uuid;l uuid;r jsonb;b uuid:=gen_random_uuid();steps int:=0;
begin
 select property_id,actor_id,lead_id into p,actor,l from fixture;
 r:=public.run_lead_score_batch(p,actor,b);
 while r->>'state'='running' and steps<30 loop r:=public.continue_lead_score_batch(p,actor,b);steps:=steps+1;end loop;
 perform pg_temp.check(r->>'state'='completed' and r->>'successful'='504' and r->>'pending'='0' and r->>'failed'='0','entire property completes beyond 500 across saved pages');
 perform pg_temp.check((select count(*)=504 from public.shared_action_events where episode_id=b and action='lead.score.recalculated'),'every completed target has one attributed action');
 perform pg_temp.check(public.run_lead_score_batch(p,actor,b)=r,'replaying completed property request returns same saved outcome');
end$$;
select count(*) as passed from checks;
ROLLBACK;
